-- Dedicated Development validation identity; never human MFA or production authority.
CREATE TABLE development_automation_identities (
 key_id TEXT PRIMARY KEY,
 name TEXT NOT NULL UNIQUE CHECK(name='development-validation'),
 account_id TEXT NOT NULL UNIQUE REFERENCES iam_accounts(id) ON DELETE RESTRICT,
 credential_version INTEGER NOT NULL CHECK(credential_version>0),
 status TEXT NOT NULL CHECK(status IN ('ACTIVE','REVOKED')),
 organization_id TEXT NOT NULL REFERENCES org_organizations(id) ON DELETE RESTRICT,
 location_id TEXT NOT NULL,
 expires_at TEXT NOT NULL,
 FOREIGN KEY(organization_id,location_id) REFERENCES org_locations(organization_id,id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE development_automation_authorizations (
 id TEXT PRIMARY KEY,
 account_id TEXT NOT NULL REFERENCES iam_accounts(id) ON DELETE RESTRICT,
 credential_version INTEGER NOT NULL CHECK(credential_version>0),
 operation TEXT NOT NULL,
 request_hash TEXT NOT NULL CHECK(length(request_hash)=64),
 expires_at TEXT NOT NULL
) STRICT;
CREATE INDEX development_automation_current_context ON development_automation_authorizations(account_id,operation,expires_at);
CREATE TABLE development_automation_nonces (
 key_id TEXT NOT NULL REFERENCES development_automation_identities(key_id) ON DELETE RESTRICT,
 nonce TEXT NOT NULL,
 expires_at TEXT NOT NULL,
 PRIMARY KEY(key_id,nonce)
) STRICT;
CREATE TABLE development_automation_resources (
 account_id TEXT NOT NULL REFERENCES iam_accounts(id) ON DELETE RESTRICT,
 resource_type TEXT NOT NULL CHECK(resource_type IN ('canonical','offering','order','vehicle','snapshot','grant')),
 resource_id TEXT NOT NULL,
 PRIMARY KEY(resource_type,resource_id)
) STRICT;
INSERT INTO authz_roles(id,scope,code) VALUES ('platform-development-automation','PLATFORM','DEVELOPMENT_AUTOMATION'),('org-development-automation','ORGANIZATION','DEVELOPMENT_AUTOMATION');
INSERT INTO authz_role_permissions(role_id,permission_code) VALUES
 ('platform-development-automation','platform.catalog.manage'),('platform-development-automation','platform.vehicle.manage'),
 ('org-development-automation','org.parts.manage'),('org-development-automation','org.workshop.read'),('org-development-automation','org.workshop.manage'),('org-development-automation','org.read'),('org-development-automation','org.location.read');
CREATE TRIGGER development_automation_identity_insert BEFORE INSERT ON development_automation_identities WHEN NOT (EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND EXISTS(SELECT 1 FROM org_organizations o JOIN org_locations l ON l.organization_id=o.id WHERE o.id=NEW.organization_id AND l.id=NEW.location_id AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE')) OR EXISTS(SELECT 1 FROM iam_accounts a JOIN platform_person_roles pr ON pr.person_id=a.person_id WHERE a.id=NEW.account_id) OR EXISTS(SELECT 1 FROM iam_accounts a JOIN org_memberships m ON m.person_id=a.person_id JOIN org_membership_roles mr ON mr.membership_id=m.id WHERE a.id=NEW.account_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_BOUNDARY'); END;
CREATE TRIGGER development_automation_identity_update BEFORE UPDATE ON development_automation_identities WHEN NOT (EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND EXISTS(SELECT 1 FROM org_organizations o JOIN org_locations l ON l.organization_id=o.id WHERE o.id=NEW.organization_id AND l.id=NEW.location_id AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE')) OR NEW.key_id IS NOT OLD.key_id OR NEW.account_id IS NOT OLD.account_id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.location_id IS NOT OLD.location_id OR NEW.name IS NOT OLD.name OR NEW.credential_version<OLD.credential_version BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_BOUNDARY'); END;
CREATE TRIGGER development_automation_platform_person_roles_insert BEFORE INSERT ON platform_person_roles WHEN (EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.person_id=NEW.person_id WHERE d.account_id=a.id) OR EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION')) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.person_id=NEW.person_id JOIN authz_roles r ON r.id=NEW.role_id WHERE d.account_id=a.id AND r.scope='PLATFORM' AND r.code='DEVELOPMENT_AUTOMATION') BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_platform_person_roles_update BEFORE UPDATE ON platform_person_roles WHEN (EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.person_id=NEW.person_id WHERE d.account_id=a.id) OR EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION')) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.person_id=NEW.person_id JOIN authz_roles r ON r.id=NEW.role_id WHERE d.account_id=a.id AND r.scope='PLATFORM' AND r.code='DEVELOPMENT_AUTOMATION') BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_org_membership_roles_insert BEFORE INSERT ON org_membership_roles WHEN (EXISTS(SELECT 1 FROM development_automation_identities d JOIN org_memberships m ON m.id=NEW.membership_id JOIN iam_accounts a ON a.person_id=m.person_id WHERE d.account_id=a.id) OR EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION')) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN org_memberships m ON m.id=NEW.membership_id JOIN iam_accounts a ON a.person_id=m.person_id JOIN authz_roles r ON r.id=NEW.role_id WHERE d.account_id=a.id AND r.scope='ORGANIZATION' AND r.code='DEVELOPMENT_AUTOMATION' AND m.organization_id=d.organization_id AND m.location_scope_type='SELECTED_LOCATIONS') BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_org_membership_roles_update BEFORE UPDATE ON org_membership_roles WHEN (EXISTS(SELECT 1 FROM development_automation_identities d JOIN org_memberships m ON m.id=NEW.membership_id JOIN iam_accounts a ON a.person_id=m.person_id WHERE d.account_id=a.id) OR EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION')) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN org_memberships m ON m.id=NEW.membership_id JOIN iam_accounts a ON a.person_id=m.person_id JOIN authz_roles r ON r.id=NEW.role_id WHERE d.account_id=a.id AND r.scope='ORGANIZATION' AND r.code='DEVELOPMENT_AUTOMATION' AND m.organization_id=d.organization_id AND m.location_scope_type='SELECTED_LOCATIONS') BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_membership_scope BEFORE UPDATE ON org_memberships WHEN EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.id=d.account_id WHERE a.person_id=OLD.person_id) AND (NEW.person_id IS NOT OLD.person_id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.location_scope_type IS NOT OLD.location_scope_type) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_SCOPE_BOUNDARY'); END;
CREATE TRIGGER development_automation_location_scope BEFORE INSERT ON org_membership_locations WHEN EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.id=d.account_id JOIN org_memberships m ON m.person_id=a.person_id WHERE m.id=NEW.membership_id) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.id=d.account_id JOIN org_memberships m ON m.person_id=a.person_id WHERE m.id=NEW.membership_id AND NEW.organization_id=d.organization_id AND NEW.location_id=d.location_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_SCOPE_BOUNDARY'); END;
CREATE TRIGGER development_automation_account_person BEFORE UPDATE OF person_id ON iam_accounts WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=OLD.id) AND NEW.person_id IS NOT OLD.person_id BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_SCOPE_BOUNDARY'); END;

DROP TRIGGER parts_canonical_insert_guard;
CREATE TRIGGER parts_canonical_insert_guard BEFORE INSERT ON parts_canonical WHEN NEW.status<>'DRAFT' OR NEW.version<>1 OR (NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN platform_person_roles pr ON pr.person_id=p.id JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND r.scope='PLATFORM' AND r.code IN ('PLATFORM_SUPERADMIN','CATALOG_ADMIN') AND rp.permission_code='platform.catalog.manage') AND NOT (EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation='parts.canonical.create' AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='canonical' AND dor.resource_id=NEW.id) AND EXISTS(SELECT 1 FROM iam_accounts ma JOIN platform_person_roles mp ON mp.person_id=ma.person_id JOIN authz_roles mr ON mr.id=mp.role_id JOIN authz_role_permissions mperm ON mperm.role_id=mr.id WHERE ma.id=NEW.last_actor_account_id AND mr.scope='PLATFORM' AND mr.code='DEVELOPMENT_AUTOMATION' AND mperm.permission_code='platform.catalog.manage'))) OR EXISTS(SELECT 1 FROM json_each(NEW.compatibility_json) c WHERE json_type(c.value)<>'object' OR json_type(c.value,'$.verified') IS NOT 'false' OR json_type(c.value,'$.vehicleKind') IS NOT 'text' OR length(json_extract(c.value,'$.vehicleKind')) NOT BETWEEN 1 AND 40 OR EXISTS(SELECT 1 FROM json_each(c.value) field WHERE field.key NOT IN ('vehicleKind','brand','model','note','verified'))) BEGIN SELECT RAISE(ABORT,'PARTS_BOUNDARY'); END;

DROP TRIGGER parts_canonical_update_guard;
CREATE TRIGGER parts_canonical_update_guard BEFORE UPDATE ON parts_canonical WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.version<>OLD.version+1 OR (NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN platform_person_roles pr ON pr.person_id=p.id JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND r.scope='PLATFORM' AND r.code IN ('PLATFORM_SUPERADMIN','CATALOG_ADMIN') AND rp.permission_code='platform.catalog.manage') AND NOT (EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation=CASE WHEN NEW.status IS NOT OLD.status THEN 'parts.canonical.transition' ELSE 'parts.canonical.update' END AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='canonical' AND dor.resource_id=NEW.id) AND EXISTS(SELECT 1 FROM iam_accounts ma JOIN platform_person_roles mp ON mp.person_id=ma.person_id JOIN authz_roles mr ON mr.id=mp.role_id JOIN authz_role_permissions mperm ON mperm.role_id=mr.id WHERE ma.id=NEW.last_actor_account_id AND mr.scope='PLATFORM' AND mr.code='DEVELOPMENT_AUTOMATION' AND mperm.permission_code='platform.catalog.manage'))) OR EXISTS(SELECT 1 FROM json_each(NEW.compatibility_json) c WHERE json_type(c.value)<>'object' OR json_type(c.value,'$.verified') IS NOT 'false' OR json_type(c.value,'$.vehicleKind') IS NOT 'text' OR length(json_extract(c.value,'$.vehicleKind')) NOT BETWEEN 1 AND 40 OR EXISTS(SELECT 1 FROM json_each(c.value) field WHERE field.key NOT IN ('vehicleKind','brand','model','note','verified'))) BEGIN SELECT RAISE(ABORT,'PARTS_BOUNDARY'); END;

DROP TRIGGER parts_offerings_insert_guard;
CREATE TRIGGER parts_offerings_insert_guard BEFORE INSERT ON parts_offerings WHEN NEW.status<>'DRAFT' OR NEW.version<>1 OR (NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=NEW.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((NEW.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=NEW.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=NEW.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=NEW.location_id AND c.code='PARTS')))) AND NOT (EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation='parts.offering.create' AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='offering' AND dor.resource_id=NEW.id) AND EXISTS(SELECT 1 FROM iam_accounts ma JOIN org_memberships mm ON mm.person_id=ma.person_id JOIN org_membership_roles mp ON mp.membership_id=mm.id JOIN authz_roles mr ON mr.id=mp.role_id JOIN development_automation_identities di ON di.account_id=ma.id JOIN authz_role_permissions mperm ON mperm.role_id=mr.id WHERE ma.id=NEW.last_actor_account_id AND mr.scope='ORGANIZATION' AND mr.code='DEVELOPMENT_AUTOMATION' AND mperm.permission_code='org.parts.manage' AND mm.status='ACTIVE' AND mm.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (mm.valid_to IS NULL OR mm.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND mm.organization_id=di.organization_id AND di.organization_id=NEW.organization_id AND di.location_id=NEW.location_id AND mm.location_scope_type='SELECTED_LOCATIONS' AND EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=mm.id AND ml.location_id=di.location_id AND ml.organization_id=di.organization_id)) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=NEW.organization_id AND c.code='PARTS') OR EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=NEW.organization_id AND c.location_id=NEW.location_id AND c.code='PARTS')) AND (NEW.canonical_part_id IS NULL OR EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='canonical' AND dor.resource_id=NEW.canonical_part_id)))) OR EXISTS(SELECT 1 FROM json_each(NEW.compatibility_json) c WHERE json_type(c.value)<>'object' OR json_type(c.value,'$.verified') IS NOT 'false' OR json_type(c.value,'$.vehicleKind') IS NOT 'text' OR length(json_extract(c.value,'$.vehicleKind')) NOT BETWEEN 1 AND 40 OR EXISTS(SELECT 1 FROM json_each(c.value) field WHERE field.key NOT IN ('vehicleKind','brand','model','note','verified'))) OR (NEW.canonical_part_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parts_canonical p WHERE p.id=NEW.canonical_part_id AND p.brand_key=NEW.brand_key AND p.reference_key=NEW.reference_key AND (NEW.status<>'ACTIVE' OR p.status='ACTIVE'))) BEGIN SELECT RAISE(ABORT,'PARTS_BOUNDARY'); END;

