CREATE TRIGGER parts_offerings_update_guard BEFORE UPDATE ON parts_offerings WHEN NEW.id IS NOT OLD.id OR NEW.created_at IS NOT OLD.created_at OR NEW.version<>OLD.version+1 OR (NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=NEW.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((NEW.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=NEW.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=NEW.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=NEW.location_id AND c.code='PARTS')))) AND NOT (EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation=CASE WHEN NEW.status IS NOT OLD.status THEN 'parts.offering.transition' ELSE 'parts.offering.update' END AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='offering' AND dor.resource_id=NEW.id) AND EXISTS(SELECT 1 FROM iam_accounts ma JOIN org_memberships mm ON mm.person_id=ma.person_id JOIN org_membership_roles mp ON mp.membership_id=mm.id JOIN authz_roles mr ON mr.id=mp.role_id JOIN development_automation_identities di ON di.account_id=ma.id JOIN authz_role_permissions mperm ON mperm.role_id=mr.id WHERE ma.id=NEW.last_actor_account_id AND mr.scope='ORGANIZATION' AND mr.code='DEVELOPMENT_AUTOMATION' AND mperm.permission_code='org.parts.manage' AND mm.status='ACTIVE' AND mm.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (mm.valid_to IS NULL OR mm.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND mm.organization_id=di.organization_id AND di.organization_id=NEW.organization_id AND di.location_id=NEW.location_id AND mm.location_scope_type='SELECTED_LOCATIONS' AND EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=mm.id AND ml.location_id=di.location_id AND ml.organization_id=di.organization_id)) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=NEW.organization_id AND c.code='PARTS') OR EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=NEW.organization_id AND c.location_id=NEW.location_id AND c.code='PARTS')) AND (NEW.canonical_part_id IS NULL OR EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='canonical' AND dor.resource_id=NEW.canonical_part_id)))) OR EXISTS(SELECT 1 FROM json_each(NEW.compatibility_json) c WHERE json_type(c.value)<>'object' OR json_type(c.value,'$.verified') IS NOT 'false' OR json_type(c.value,'$.vehicleKind') IS NOT 'text' OR length(json_extract(c.value,'$.vehicleKind')) NOT BETWEEN 1 AND 40 OR EXISTS(SELECT 1 FROM json_each(c.value) field WHERE field.key NOT IN ('vehicleKind','brand','model','note','verified'))) OR NEW.organization_id IS NOT OLD.organization_id OR (NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=OLD.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((OLD.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (OLD.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=OLD.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=OLD.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (OLD.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=OLD.location_id AND c.code='PARTS')))) AND NOT (EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation=CASE WHEN NEW.status IS NOT OLD.status THEN 'parts.offering.transition' ELSE 'parts.offering.update' END AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='offering' AND dor.resource_id=NEW.id) AND EXISTS(SELECT 1 FROM iam_accounts ma JOIN org_memberships mm ON mm.person_id=ma.person_id JOIN org_membership_roles mp ON mp.membership_id=mm.id JOIN authz_roles mr ON mr.id=mp.role_id JOIN development_automation_identities di ON di.account_id=ma.id JOIN authz_role_permissions mperm ON mperm.role_id=mr.id WHERE ma.id=NEW.last_actor_account_id AND mr.scope='ORGANIZATION' AND mr.code='DEVELOPMENT_AUTOMATION' AND mperm.permission_code='org.parts.manage' AND mm.status='ACTIVE' AND mm.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (mm.valid_to IS NULL OR mm.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND mm.organization_id=di.organization_id AND di.organization_id=OLD.organization_id AND di.location_id=OLD.location_id AND mm.location_scope_type='SELECTED_LOCATIONS' AND EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=mm.id AND ml.location_id=di.location_id AND ml.organization_id=di.organization_id)) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=NEW.organization_id AND c.code='PARTS') OR EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=NEW.organization_id AND c.location_id=NEW.location_id AND c.code='PARTS')) AND (NEW.canonical_part_id IS NULL OR EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.last_actor_account_id AND dor.resource_type='canonical' AND dor.resource_id=NEW.canonical_part_id)))) OR (NEW.canonical_part_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parts_canonical p WHERE p.id=NEW.canonical_part_id AND p.brand_key=NEW.brand_key AND p.reference_key=NEW.reference_key AND (NEW.status<>'ACTIVE' OR p.status='ACTIVE'))) BEGIN SELECT RAISE(ABORT,'PARTS_BOUNDARY'); END;

DROP TRIGGER parts_workshop_snapshot_guard;
CREATE TRIGGER parts_workshop_snapshot_guard BEFORE INSERT ON parts_workshop_snapshots WHEN NOT EXISTS(
 SELECT 1 FROM workshop_orders w JOIN parts_offerings f ON f.id=NEW.offering_id JOIN iam_accounts a ON a.id=NEW.actor_account_id JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id AND m.organization_id=w.organization_id JOIN org_organizations o ON o.id=m.organization_id JOIN org_locations l ON l.id=w.location_id AND l.organization_id=o.id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_role_permissions rp ON rp.role_id=mr.role_id JOIN authz_roles r ON r.id=mr.role_id
 WHERE w.id=NEW.order_id AND w.organization_id=NEW.organization_id AND w.location_id=NEW.location_id AND w.version=NEW.order_version AND w.status IN ('DRAFT','OPEN','IN_PROGRESS')
 AND ((a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1)) OR EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.actor_account_id))
 AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.status='ACTIVE' AND r.scope='ORGANIZATION' AND rp.permission_code='org.workshop.manage'
 AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=l.id))
 AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code IN ('CAR_SERVICE','MOTORCYCLE_SERVICE','GENERAL_MAINTENANCE','ELECTRICAL','DIAGNOSTICS','TIRES','BODYWORK')) OR EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=l.id AND c.code IN ('CAR_SERVICE','MOTORCYCLE_SERVICE','GENERAL_MAINTENANCE','ELECTRICAL','DIAGNOSTICS','TIRES','BODYWORK')))
 AND EXISTS(SELECT 1 FROM vehicle_access_grants g WHERE g.vehicle_id=w.vehicle_id AND g.permission_code='vehicle.workshop.write' AND g.granted_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND g.revoked_at IS NULL AND (g.expires_at IS NULL OR g.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND (g.person_id=p.id OR (g.organization_id=o.id AND (g.location_id IS NULL OR g.location_id=l.id))))
 AND f.organization_id=o.id AND (f.location_id IS NULL OR f.location_id=l.id) AND f.status='ACTIVE' AND f.version=NEW.offering_version AND f.canonical_part_id IS NEW.canonical_part_id
 AND (f.canonical_part_id IS NULL OR EXISTS(SELECT 1 FROM parts_canonical c WHERE c.id=f.canonical_part_id AND c.status='ACTIVE' AND c.version=NEW.canonical_version AND c.brand_key=f.brand_key AND c.reference_key=f.reference_key))
 AND json_extract(NEW.snapshot_json,'$.name') IS f.name AND json_extract(NEW.snapshot_json,'$.brand') IS f.brand AND json_extract(NEW.snapshot_json,'$.manufacturerReference') IS f.manufacturer_reference AND json_extract(NEW.snapshot_json,'$.priceMinor') IS f.price_minor AND json_extract(NEW.snapshot_json,'$.currency') IS f.currency AND json_extract(NEW.snapshot_json,'$.unit') IS f.unit
) BEGIN SELECT RAISE(ABORT,'PARTS_SNAPSHOT_BOUNDARY'); END;

CREATE TRIGGER development_automation_resources_no_update BEFORE UPDATE ON development_automation_resources BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_RESOURCE_BOUNDARY'); END;
CREATE TRIGGER development_automation_resources_no_delete BEFORE DELETE ON development_automation_resources BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_RESOURCE_BOUNDARY'); END;
CREATE TRIGGER development_automation_identity_no_delete BEFORE DELETE ON development_automation_identities BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_BOUNDARY'); END;
CREATE TRIGGER development_automation_location_scope_update BEFORE UPDATE ON org_membership_locations WHEN EXISTS(SELECT 1 FROM development_automation_identities d JOIN iam_accounts a ON a.id=d.account_id JOIN org_memberships m ON m.person_id=a.person_id WHERE m.id=OLD.membership_id OR m.id=NEW.membership_id) AND (NEW.membership_id IS NOT OLD.membership_id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.location_id IS NOT OLD.location_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_SCOPE_BOUNDARY'); END;

CREATE TRIGGER development_automation_identity_machine_only BEFORE INSERT ON development_automation_identities WHEN EXISTS(SELECT 1 FROM auth_users u WHERE u.id=NEW.account_id AND u.two_factor_enabled<>0) OR EXISTS(SELECT 1 FROM auth_credentials c WHERE c.user_id=NEW.account_id) OR EXISTS(SELECT 1 FROM auth_sessions c WHERE c.user_id=NEW.account_id) OR EXISTS(SELECT 1 FROM auth_two_factors c WHERE c.user_id=NEW.account_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_credentials_insert BEFORE INSERT ON auth_credentials WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_credentials_update BEFORE UPDATE ON auth_credentials WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id OR d.account_id=OLD.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_sessions_insert BEFORE INSERT ON auth_sessions WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_sessions_update BEFORE UPDATE ON auth_sessions WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id OR d.account_id=OLD.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_two_factors_insert BEFORE INSERT ON auth_two_factors WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_auth_two_factors_update BEFORE UPDATE ON auth_two_factors WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.user_id OR d.account_id=OLD.user_id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_no_human_mfa BEFORE UPDATE OF two_factor_enabled ON auth_users WHEN NEW.two_factor_enabled<>0 AND EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=OLD.id) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_HUMAN_AUTH_BOUNDARY'); END;
CREATE TRIGGER development_automation_resource_insert BEFORE INSERT ON development_automation_resources WHEN NOT EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations c ON c.account_id=d.account_id AND c.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.operation=CASE NEW.resource_type WHEN 'canonical' THEN 'parts.canonical.create' WHEN 'offering' THEN 'parts.offering.create' WHEN 'order' THEN 'workshop.order.create' WHEN 'vehicle' THEN 'vehicle.create' WHEN 'snapshot' THEN 'parts.workshop.snapshot.add' WHEN 'grant' THEN 'vehicle.grant.create' END AND a.status='ACTIVE' AND p.status='ACTIVE' AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development')) OR (NEW.resource_type='canonical' AND EXISTS(SELECT 1 FROM parts_canonical r WHERE r.id=NEW.resource_id)) OR (NEW.resource_type='offering' AND EXISTS(SELECT 1 FROM parts_offerings r WHERE r.id=NEW.resource_id)) OR (NEW.resource_type='order' AND EXISTS(SELECT 1 FROM workshop_orders r WHERE r.id=NEW.resource_id)) OR (NEW.resource_type='vehicle' AND EXISTS(SELECT 1 FROM vehicle_vehicles r WHERE r.id=NEW.resource_id)) OR (NEW.resource_type='snapshot' AND EXISTS(SELECT 1 FROM parts_workshop_snapshots r WHERE r.id=NEW.resource_id)) OR (NEW.resource_type='grant' AND EXISTS(SELECT 1 FROM vehicle_access_grants r WHERE r.id=NEW.resource_id)) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_RESOURCE_BOUNDARY'); END;

CREATE TRIGGER parts_workshop_snapshot_machine_guard BEFORE INSERT ON parts_workshop_snapshots WHEN EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.actor_account_id) AND NOT EXISTS(SELECT 1 FROM workshop_orders w JOIN iam_accounts a ON a.id=NEW.actor_account_id JOIN iam_people p ON p.id=a.person_id JOIN org_memberships m ON m.person_id=p.id AND m.organization_id=w.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id WHERE w.id=NEW.order_id AND EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id JOIN org_organizations o ON o.id=d.organization_id JOIN org_locations l ON l.id=d.location_id AND l.organization_id=o.id WHERE d.account_id=NEW.actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation='parts.workshop.snapshot.add' AND a.status='ACTIVE' AND p.status='ACTIVE' AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND o.type='WORKSHOP' AND o.display_name='MotorBaldi Development Validation Workshop' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND l.name='MotorBaldi Development Workshop Site' AND l.status='ACTIVE') AND r.code='DEVELOPMENT_AUTOMATION' AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.actor_account_id AND dor.resource_type='order' AND dor.resource_id=NEW.order_id) AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.actor_account_id AND dor.resource_type='offering' AND dor.resource_id=NEW.offering_id) AND EXISTS(SELECT 1 FROM development_automation_resources dor WHERE dor.account_id=NEW.actor_account_id AND dor.resource_type='vehicle' AND dor.resource_id=w.vehicle_id) AND EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.actor_account_id AND d.organization_id=w.organization_id AND d.location_id=w.location_id)) BEGIN SELECT RAISE(ABORT,'PARTS_SNAPSHOT_BOUNDARY'); END;

CREATE TRIGGER development_automation_role_identity_update BEFORE UPDATE ON authz_roles WHEN (OLD.code='DEVELOPMENT_AUTOMATION' OR NEW.code='DEVELOPMENT_AUTOMATION') AND (NEW.id IS NOT OLD.id OR NEW.code IS NOT OLD.code OR NEW.scope IS NOT OLD.scope) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_role_permission_insert BEFORE INSERT ON authz_role_permissions WHEN EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION' AND ((r.scope='PLATFORM' AND NEW.permission_code NOT IN ('platform.catalog.manage','platform.vehicle.manage')) OR (r.scope='ORGANIZATION' AND NEW.permission_code NOT IN ('org.parts.manage','org.workshop.read','org.workshop.manage','org.read','org.location.read')))) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
CREATE TRIGGER development_automation_role_permission_update BEFORE UPDATE ON authz_role_permissions WHEN EXISTS(SELECT 1 FROM authz_roles r WHERE r.id=NEW.role_id AND r.code='DEVELOPMENT_AUTOMATION' AND ((r.scope='PLATFORM' AND NEW.permission_code NOT IN ('platform.catalog.manage','platform.vehicle.manage')) OR (r.scope='ORGANIZATION' AND NEW.permission_code NOT IN ('org.parts.manage','org.workshop.read','org.workshop.manage','org.read','org.location.read')))) BEGIN SELECT RAISE(ABORT,'DEVELOPMENT_AUTOMATION_ROLE_BOUNDARY'); END;
